TASK
Map an iterable through asynchronous work with configured concurrency and ordered results.

PUBLIC CONTRACT
Module: await load('./index.js'); default export pMap, named exports pMapIterable and pMapSkip.
pMap(input, mapper, options?) returns a Promise of mapped values in input order. Inputs may be synchronous or asynchronous iterables and contain values or promises. Mapper receives (resolvedValue, inputIndex), and may return a value or promise. concurrency is an integer >=1 or Infinity (default Infinity). Empty input yields []. Returning pMapSkip omits that item. With stopOnError=true (default), an input or mapper rejection rejects the result; false waits for mapper work and aggregates mapper errors. A supplied AbortSignal cancels the operation using its reason.
pMapIterable(input, mapper, options?) returns an async iterable yielding mapped values in input order. concurrency bounds simultaneous mapper work; backpressure (default concurrency) bounds buffered results and must be >=concurrency. Mapper receives the resolved value and its input index. Mapper failures propagate to the consumer. pMapSkip omits an item.
Keep iteration, error propagation, ordering, and configured work limits consistent for ordinary values, promise inputs, and async sources.

SOURCE index.js
   1: export default async function pMap(
   2: 	iterable,
   3: 	mapper,
   4: 	{
   5: 		concurrency = Number.POSITIVE_INFINITY,
   6: 		stopOnError = true,
   7: 		signal,
   8: 	} = {},
   9: ) {
  10: 	return new Promise((resolve_, reject_) => {
  11: 		if (iterable[Symbol.iterator] === undefined && iterable[Symbol.asyncIterator] === undefined) {
  12: 			throw new TypeError(`Expected \`input\` to be either an \`Iterable\` or \`AsyncIterable\`, got (${typeof iterable})`);
  13: 		}
  14: 
  15: 		if (typeof mapper !== 'function') {
  16: 			throw new TypeError('Mapper function is required');
  17: 		}
  18: 
  19: 		if (!((Number.isSafeInteger(concurrency) && concurrency >= 1) || concurrency === Number.POSITIVE_INFINITY)) {
  20: 			throw new TypeError(`Expected \`concurrency\` to be an integer from 1 and up or \`Infinity\`, got \`${concurrency}\` (${typeof concurrency})`);
  21: 		}
  22: 
  23: 		const result = [];
  24: 		const errors = [];
  25: 		const skippedIndexesMap = new Map();
  26: 		let isRejected = false;
  27: 		let isResolved = false;
  28: 		let isIterableDone = false;
  29: 		let resolvingCount = 0;
  30: 		let currentIndex = 0;
  31: 		const iterator = iterable[Symbol.asyncIterator] === undefined ? iterable[Symbol.iterator]() : iterable[Symbol.asyncIterator]();
  32: 
  33: 		const signalListener = () => {
  34: 			reject(signal.reason);
  35: 		};
  36: 
  37: 		const cleanup = () => {
  38: 			signal?.removeEventListener('abort', signalListener);
  39: 		};
  40: 
  41: 		const resolve = value => {
  42: 			resolve_(value);
  43: 			cleanup();
  44: 		};
  45: 
  46: 		const reject = reason => {
  47: 			if (isResolved) {
  48: 				return;
  49: 			}
  50: 
  51: 			isRejected = true;
  52: 			isResolved = true;
  53: 			reject_(reason);
  54: 			cleanup();
  55: 
  56: 			if (!isIterableDone) {
  57: 				closeIterator(iterator);
  58: 			}
  59: 		};
  60: 
  61: 		if (signal) {
  62: 			if (signal.aborted) {
  63: 				reject(signal.reason);
  64: 				return;
  65: 			}
  66: 
  67: 			signal.addEventListener('abort', signalListener, {once: true});
  68: 		}
  69: 
  70: 		const next = async () => {
  71: 			if (isResolved) {
  72: 				return;
  73: 			}
  74: 
  75: 			// Once the source reported `done`, don't pull again like `for await`. A source like a queue may block in `next()` after it is exhausted, which would hang the completion below.
  76: 			const nextItem = isIterableDone ? {done: true} : await iterator.next();
  77: 
  78: 			const index = currentIndex;
  79: 			currentIndex++;
  80: 
  81: 			// Note: `iterator.next()` can be called many times in parallel.
  82: 			// This can cause multiple calls to this `next()` function to
  83: 			// receive a `nextItem` with `done === true`.
  84: 			// The shutdown logic that rejects/resolves must be protected
  85: 			// so it runs only one time as the `skippedIndex` logic is
  86: 			// non-idempotent.
  87: 			if (nextItem.done) {
  88: 				isIterableDone = true;
  89: 
  90: 				if (resolvingCount === 0 && !isResolved) {
  91: 					if (!stopOnError && errors.length > 0) {
  92: 						reject(new AggregateError(errors)); // eslint-disable-line unicorn/error-message
  93: 						return;
  94: 					}
  95: 
  96: 					isResolved = true;
  97: 
  98: 					if (skippedIndexesMap.size === 0) {
  99: 						resolve(result);
 100: 						return;
 101: 					}
 102: 
 103: 					const pureResult = [];
 104: 
 105: 					// Support multiple `pMapSkip`'s.
 106: 					for (const [index, value] of result.entries()) {
 107: 						if (skippedIndexesMap.get(index) === pMapSkip) {
 108: 							continue;
 109: 						}
 110: 
 111: 						pureResult.push(value);
 112: 					}
 113: 
 114: 					resolve(pureResult);
 115: 				}
 116: 
 117: 				return;
 118: 			}
 119: 
 120: 			resolvingCount++;
 121: 
 122: 			// Intentionally detached
 123: 			(async () => {
 124: 				try {
 125: 					const element = await nextItem.value;
 126: 
 127: 					if (isResolved) {
 128: 						return;
 129: 					}
 130: 
 131: 					const value = await mapper(element, index);
 132: 
 133: 					// Use Map to stage the index of the element.
 134: 					if (value === pMapSkip) {
 135: 						skippedIndexesMap.set(index, value);
 136: 					}
 137: 
 138: 					result[index] = value;
 139: 				} catch (error) {
 140: 					if (stopOnError) {
 141: 						reject(error);
 142: 						return;
 143: 					}
 144: 
 145: 					errors.push(error);
 146: 				}
 147: 
 148: 				resolvingCount--;
 149: 
 150: 				// If the iterable throws we can't really continue regardless of `stopOnError` state
 151: 				// since an iterable is likely to continue throwing after it throws once.
 152: 				// If we continue calling `next()` indefinitely we will likely end up
 153: 				// in an infinite loop of failed iteration.
 154: 				try {
 155: 					await next();
 156: 				} catch (error) {
 157: 					reject(error);
 158: 				}
 159: 			})();
 160: 		};
 161: 
 162: 		// Create the concurrent runners in a detached (non-awaited)
 163: 		// promise. We need this so we can await the `next()` calls
 164: 		// to stop creating runners before hitting the concurrency limit
 165: 		// if the iterable has already been marked as done.
 166: 		// NOTE: We *must* do this for async iterators otherwise we'll spin up
 167: 		// infinite `next()` calls by default and never start the event loop.
 168: 		(async () => {
 169: 			for (let index = 0; index < concurrency; index++) {
 170: 				try {
 171: 					// eslint-disable-next-line no-await-in-loop
 172: 					await next();
 173: 				} catch (error) {
 174: 					reject(error);
 175: 					break;
 176: 				}
 177: 
 178: 				if (isIterableDone || isRejected) {
 179: 					break;
 180: 				}
 181: 			}
 182: 		})();
 183: 	});
 184: }
 185: 
 186: export function pMapIterable(
 187: 	iterable,
 188: 	mapper,
 189: 	{
 190: 		concurrency = Number.POSITIVE_INFINITY,
 191: 		backpressure = concurrency,
 192: 	} = {},
 193: ) {
 194: 	if (iterable[Symbol.iterator] === undefined && iterable[Symbol.asyncIterator] === undefined) {
 195: 		throw new TypeError(`Expected \`input\` to be either an \`Iterable\` or \`AsyncIterable\`, got (${typeof iterable})`);
 196: 	}
 197: 
 198: 	if (typeof mapper !== 'function') {
 199: 		throw new TypeError('Mapper function is required');
 200: 	}
 201: 
 202: 	if (!((Number.isSafeInteger(concurrency) && concurrency >= 1) || concurrency === Number.POSITIVE_INFINITY)) {
 203: 		throw new TypeError(`Expected \`concurrency\` to be an integer from 1 and up or \`Infinity\`, got \`${concurrency}\` (${typeof concurrency})`);
 204: 	}
 205: 
 206: 	if (!((Number.isSafeInteger(backpressure) && backpressure >= concurrency) || backpressure === Number.POSITIVE_INFINITY)) {
 207: 		throw new TypeError(`Expected \`backpressure\` to be an integer from \`concurrency\` (${concurrency}) and up or \`Infinity\`, got \`${backpressure}\` (${typeof backpressure})`);
 208: 	}
 209: 
 210: 	return {
 211: 		async * [Symbol.asyncIterator]() {
 212: 			const iterator = iterable[Symbol.asyncIterator] === undefined ? iterable[Symbol.iterator]() : iterable[Symbol.asyncIterator]();
 213: 
 214: 			const promises = [];
 215: 			let pendingPromisesCount = 0;
 216: 			let isDone = false;
 217: 			let isIterableDone = false;
 218: 			let index = 0;
 219: 
 220: 			function trySpawn() {
 221: 				if (isDone || !(pendingPromisesCount < concurrency && promises.length < backpressure)) {
 222: 					return;
 223: 				}
 224: 
 225: 				pendingPromisesCount++;
 226: 
 227: 				// Errors must be returned as a value instead of rejecting, otherwise a promise that
 228: 				// the consumer abandons after an earlier error becomes an unhandled rejection.
 229: 				const promise = (async () => {
 230: 					try {
 231: 						const {done, value} = await iterator.next();
 232: 
 233: 						if (done) {
 234: 							isIterableDone = true;
 235: 							pendingPromisesCount--;
 236: 							return {done: true};
 237: 						}
 238: 
 239: 						// Spawn if still below concurrency and backpressure limit
 240: 						trySpawn();
 241: 
 242: 						const currentIndex = index++;
 243: 						const element = await value;
 244: 
 245: 						// The consumer stopped iterating or a mapper threw while this input was pending, so drop it instead of doing work nobody will consume.
 246: 						if (isDone) {
 247: 							pendingPromisesCount--;
 248: 							return {done: false, value: pMapSkip};
 249: 						}
 250: 
 251: 						const returnValue = await mapper(element, currentIndex);
 252: 
 253: 						pendingPromisesCount--;
 254: 
 255: 						if (returnValue === pMapSkip) {
 256: 							const index = promises.indexOf(promise);
 257: 
 258: 							if (index > 0) {
 259: 								promises.splice(index, 1);
 260: 							}
 261: 						}
 262: 
 263: 						// Spawn if still below backpressure limit and just dropped below concurrency limit
 264: 						trySpawn();
 265: 
 266: 						return {done: false, value: returnValue};
 267: 					} catch (error) {
 268: 						pendingPromisesCount--;
 269: 						isDone = true;
 270: 						return {error};
 271: 					}
 272: 				})();
 273: 
 274: 				promises.push(promise);
 275: 			}
 276: 
 277: 			trySpawn();
 278: 
 279: 			try {
 280: 				while (promises.length > 0) {
 281: 					const result = await promises[0]; // eslint-disable-line no-await-in-loop
 282: 					const {done, value} = result;
 283: 
 284: 					promises.shift();
 285: 
 286: 					if (Object.hasOwn(result, 'error')) {
 287: 						throw result.error;
 288: 					}
 289: 
 290: 					if (done) {
 291: 						return;
 292: 					}
 293: 
 294: 					// Spawn if just dropped below backpressure limit and below the concurrency limit
 295: 					trySpawn();
 296: 
 297: 					if (value === pMapSkip) {
 298: 						continue;
 299: 					}
 300: 
 301: 					yield value;
 302: 				}
 303: 			} finally {
 304: 				// Stop pulling input once the consumer stops iterating, otherwise pending skipped mappers keep spawning work.
 305: 				isDone = true;
 306: 
 307: 				if (!isIterableDone) {
 308: 					closeIterator(iterator);
 309: 				}
 310: 			}
 311: 		},
 312: 	};
 313: }
 314: 
 315: export const pMapSkip = Symbol('skip');
 316: 
 317: // Close the source so it can release its resources, like `for await` does.
 318: // Callers must not await this so a source that is blocked in `next()` cannot block them.
 319: async function closeIterator(iterator) {
 320: 	try {
 321: 		await iterator.return?.();
 322: 	} catch {}
 323: }

